package io.mavsdk.kotlin.plugins.modes

import io.mavsdk.jni.plugins.modes.NativeModes
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

private fun Modes.Mode.toNative(): NativeModes.Mode =
    NativeModes.Mode(name, isStandard, customMode, isUserSelectable, isAdvanced, isAutoMode)

private fun NativeModes.Mode.toKotlin(): Modes.Mode =
    Modes.Mode(name, isStandard, customMode, isUserSelectable, isAdvanced, isAutoMode)

private class ModesNativeImpl(private val handle: Long) : ModesNative {
    // The read lock keeps `handle` alive for the duration of a native call; destroy()
    // takes the write lock, which waits for in-flight calls to finish. Readers do not
    // exclude each other, so independent calls on this plugin still run concurrently
    // and cancelling a subscription does not queue behind a slow blocking call.
    private val lifecycle = ReentrantReadWriteLock()
    @Volatile private var destroyed = false
    private val activeSubscriptions = ConcurrentHashMap<Long, () -> Unit>()

    private inline fun <Value> withOpen(action: () -> Value): Value = lifecycle.read {
        check(!destroyed) { "Modes is closed" }
        action()
    }

    override fun availableModes(): List<Modes.Mode> = withOpen {
        val value = NativeModes.availableModes(handle)
        value.map { it.toKotlin() }
    }

    override fun subscribeAvailableModes(callback: (List<Modes.Mode>) -> Unit): Long = withOpen {
        val subscriptionHandle =
            NativeModes.subscribeAvailableModes(
                handle,
                NativeModes.AvailableModesCallback { value ->
                    callback(value.map { it.toKotlin() })
                },
            )
        if (subscriptionHandle != 0L) {
            activeSubscriptions[subscriptionHandle] = {
                NativeModes.unsubscribeAvailableModes(handle, subscriptionHandle)
            }
        }
        subscriptionHandle
    }

    override fun unsubscribeAvailableModes(subscriptionHandle: Long) {
        // No destroyed check: flow cancellation races teardown, and destroy() already
        // drained the map, so this is a no-op rather than an error after close.
        lifecycle.read { activeSubscriptions.remove(subscriptionHandle)?.invoke() }
    }

    override fun currentMode(): Modes.Mode = withOpen {
        val value = NativeModes.currentMode(handle)
        value.toKotlin()
    }

    override fun subscribeCurrentMode(callback: (Modes.Mode) -> Unit): Long = withOpen {
        val subscriptionHandle =
            NativeModes.subscribeCurrentMode(
                handle,
                NativeModes.CurrentModeCallback { value -> callback(value.toKotlin()) },
            )
        if (subscriptionHandle != 0L) {
            activeSubscriptions[subscriptionHandle] = {
                NativeModes.unsubscribeCurrentMode(handle, subscriptionHandle)
            }
        }
        subscriptionHandle
    }

    override fun unsubscribeCurrentMode(subscriptionHandle: Long) {
        // No destroyed check: flow cancellation races teardown, and destroy() already
        // drained the map, so this is a no-op rather than an error after close.
        lifecycle.read { activeSubscriptions.remove(subscriptionHandle)?.invoke() }
    }

    override fun setModeAsync(name: String, callback: (Int) -> Unit) {
        withOpen {
            NativeModes.setModeAsync(
                handle,
                name,
                NativeModes.SetModeCallback { result -> callback(result) },
            )
        }
    }

    override fun destroy() {
        lifecycle.write {
            if (destroyed) return
            destroyed = true
            activeSubscriptions.keys.toList().forEach { subscriptionHandle ->
                activeSubscriptions.remove(subscriptionHandle)?.invoke()
            }
            NativeModes.destroy(handle)
        }
    }
}

internal actual fun createModesNative(systemHandle: Long): ModesNative =
    ModesNativeImpl(NativeModes.create(systemHandle))

internal actual class ModesCallbackGuard actual constructor() {
    private val claimed = AtomicBoolean(false)

    actual fun tryClaim(): Boolean = claimed.compareAndSet(false, true)
}
